"""Next firing times of a five-field cron expression. See task.md."""

from __future__ import annotations

from datetime import datetime, timedelta


class CronError(ValueError):
    """Raised for malformed expressions and for searches that find nothing."""


_MONTH_NAMES = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

_DOW_NAMES = {
    "SUN": 0, "MON": 1, "TUE": 2, "WED": 3, "THU": 4, "FRI": 5, "SAT": 6,
}


def _parse_value(token: str, lo: int, hi: int, names: dict[str, int] | None) -> int:
    token = token.strip()
    if names is not None and token.upper() in names:
        value = names[token.upper()]
    else:
        try:
            value = int(token)
        except ValueError:
            raise CronError(f"invalid value {token!r}")
    if not (lo <= value <= hi):
        raise CronError(f"value {value} out of range [{lo}, {hi}]")
    return value


def _parse_field(
    text: str, lo: int, hi: int, names: dict[str, int] | None = None
) -> tuple[set[int], bool]:
    text = text.strip()
    if not text:
        raise CronError("empty field")
    restricted = text != "*"

    values: set[int] = set()
    for term in text.split(","):
        term = term.strip()
        if not term:
            raise CronError("empty term")

        if "/" in term:
            base, step_s = term.split("/", 1)
            try:
                step = int(step_s)
            except ValueError:
                raise CronError(f"invalid step {step_s!r}")
            if step < 1:
                raise CronError("step must be >= 1")

            if base == "*":
                lo_v, hi_v = lo, hi
            elif "-" in base:
                a_s, b_s = base.split("-", 1)
                lo_v = _parse_value(a_s, lo, hi, names)
                hi_v = _parse_value(b_s, lo, hi, names)
                if lo_v > hi_v:
                    raise CronError("range low bound above high bound")
            else:
                lo_v = _parse_value(base, lo, hi, names)
                hi_v = hi
            values.update(range(lo_v, hi_v + 1, step))
        elif term == "*":
            values.update(range(lo, hi + 1))
        elif "-" in term:
            a_s, b_s = term.split("-", 1)
            lo_v = _parse_value(a_s, lo, hi, names)
            hi_v = _parse_value(b_s, lo, hi, names)
            if lo_v > hi_v:
                raise CronError("range low bound above high bound")
            values.update(range(lo_v, hi_v + 1))
        else:
            values.add(_parse_value(term, lo, hi, names))

    return values, restricted


def _day_matches(
    date,
    dom_values: set[int],
    dow_values: set[int],
    dom_restricted: bool,
    dow_restricted: bool,
) -> bool:
    dom_match = date.day in dom_values
    cron_dow = (date.weekday() + 1) % 7  # Monday=0..Sunday=6 -> Sunday=0..Saturday=6
    dow_match = cron_dow in dow_values

    if dom_restricted and dow_restricted:
        return dom_match or dow_match
    if dom_restricted:
        return dom_match
    if dow_restricted:
        return dow_match
    return True


def next_firings(expr: str, start: datetime, count: int) -> list[datetime]:
    """Return the next `count` firing times strictly after `start`."""
    if count == 0:
        return []

    fields = expr.split()
    if len(fields) != 5:
        raise CronError(f"expected 5 fields, got {len(fields)}")
    minute_f, hour_f, dom_f, month_f, dow_f = fields

    minute_values, _ = _parse_field(minute_f, 0, 59)
    hour_values, _ = _parse_field(hour_f, 0, 23)
    dom_values, dom_restricted = _parse_field(dom_f, 1, 31)
    month_values, _ = _parse_field(month_f, 1, 12, _MONTH_NAMES)
    dow_values, dow_restricted = _parse_field(dow_f, 0, 7, _DOW_NAMES)
    dow_values = {0 if v == 7 else v for v in dow_values}

    minute_sorted = sorted(minute_values)
    hour_sorted = sorted(hour_values)

    first_candidate = start.replace(second=0, microsecond=0) + timedelta(minutes=1)

    try:
        limit_dt = start.replace(year=start.year + 5)
    except ValueError:
        # start was Feb 29 on a leap year; fall back to Feb 28.
        limit_dt = start.replace(year=start.year + 5, day=28)
    limit_date = limit_dt.date()

    results: list[datetime] = []
    day = first_candidate.date()
    first_day = True

    while day <= limit_date:
        if day.month in month_values and _day_matches(
            day, dom_values, dow_values, dom_restricted, dow_restricted
        ):
            for h in hour_sorted:
                for m in minute_sorted:
                    candidate = datetime(day.year, day.month, day.day, h, m)
                    if first_day and candidate < first_candidate:
                        continue
                    results.append(candidate)
                    if len(results) == count:
                        return results
        day = day + timedelta(days=1)
        first_day = False

    raise CronError("no firing found within five years of start")
